// Toma el archivo subido en el formulario y arma la petición para la API de Claude.
const PROMPT = "Eres un asistente que lee documentos tributarios chilenos (facturas, boletas, notas de crédito).\nLee el documento adjunto y responde SOLO con un objeto JSON, sin texto adicional, con estas claves:\n{\"tipo\": \"factura\" | \"boleta\" | \"nota_credito\" | \"otro\", \"emisor\": razón social del emisor, \"rut_emisor\": RUT del emisor tal como aparece, \"folio\": número del documento como texto, \"fecha\": fecha de emisión AAAA-MM-DD, \"neto\": número entero o null, \"iva\": número entero o null, \"exento\": número entero o null, \"total\": número entero}\nCopia los montos exactamente como están impresos, aunque no cuadren. Si un dato no se lee, usa null.";
const MODELO = 'claude-sonnet-5-5'; // cámbialo por 'claude-haiku-5-5' para gastar menos

const item = $input.first();
const clave = Object.keys(item.binary || {})[0];
if (!clave) throw new Error('El formulario no trajo ningún archivo.');
const archivo = item.binary[clave];
const buffer = await this.helpers.getBinaryDataBuffer(0, clave);
if (buffer.length > 5 * 1024 * 1024) throw new Error('El archivo pesa más de 5 MB. Sube una foto más liviana.');
const base64 = buffer.toString('base64');

const esPdf = archivo.mimeType === 'application/pdf';
const bloque = esPdf
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } }
  : { type: 'image', source: { type: 'base64', media_type: archivo.mimeType, data: base64 } };

return [{
  json: {
    archivo: archivo.fileName,
    body: { model: MODELO, max_tokens: 800, messages: [{ role: 'user', content: [bloque, { type: 'text', text: PROMPT }] }] },
  },
}];

// Lee la respuesta de Claude y valida el documento con reglas fijas (sin IA).
const respuesta = $input.first().json;
const texto = (respuesta.content || []).map((c) => c.text || '').join('');
const ini = texto.indexOf('{'), fin = texto.lastIndexOf('}');
if (ini < 0 || fin < ini) throw new Error('Claude no devolvió un JSON legible: ' + texto.slice(0, 200));
const d = JSON.parse(texto.slice(ini, fin + 1));

const num = (x) => {
  if (typeof x === 'number') return x;
  if (x == null || x === '') return null;
  const n = parseFloat(String(x).replace(/[$\s.]/g, '').replace(',', '.'));
  return isNaN(n) ? null : n;
};
const limpiarRut = (r) => String(r || '').toUpperCase().replace(/[^0-9K]/g, '');
const dv = (cuerpo) => {
  let suma = 0, mult = 2;
  for (const c of String(cuerpo).split('').reverse()) { suma += Number(c) * mult; mult = mult === 7 ? 2 : mult + 1; }
  const r = 11 - (suma % 11);
  return r === 11 ? '0' : r === 10 ? 'K' : String(r);
};

const obs = [];
const neto = num(d.neto), iva = num(d.iva), exento = num(d.exento) || 0, total = num(d.total);
for (const [k, nombre] of [['emisor', 'emisor'], ['rut_emisor', 'RUT'], ['folio', 'folio'], ['fecha', 'fecha'], ['total', 'total']])
  if (d[k] == null || d[k] === '') obs.push('Falta ' + nombre);
const rut = limpiarRut(d.rut_emisor);
if (rut.length > 1 && dv(rut.slice(0, -1)) !== rut.slice(-1)) obs.push('RUT con dígito verificador incorrecto');
if (d.tipo === 'factura' && neto != null && iva != null && Math.abs(Math.round(neto * 0.19) - iva) > 2)
  obs.push('IVA no es el 19% del neto (debería ser ' + Math.round(neto * 0.19) + ')');
if (neto != null && total != null && Math.abs(neto + (iva || 0) + exento - total) > 2)
  obs.push('El total no cuadra con neto + IVA + exento');

return [{
  json: {
    fecha_carga: typeof $now !== 'undefined' ? $now.toISODate() : new Date().toISOString().slice(0, 10),
    archivo: $('Preparar archivo').first().json.archivo,
    tipo: d.tipo, emisor: d.emisor, rut_emisor: d.rut_emisor, folio: d.folio, fecha: d.fecha,
    neto, iva, exento: num(d.exento), total,
    estado: obs.length ? 'REVISAR' : 'OK',
    observaciones: obs.join(' | '),
  },
}];
